import { useState, useEffect } from "react";

const BG_IMAGE  = "data:image/png;base64,";
const ISPM_LOGO = "data:image/png;base64,";

// Logo SVG professionnel SFIGP
function SfigpLogo({ size = 40 }) {
  return (
    <div style={{
      width:size, height:size, borderRadius:size*0.25,
      background:"linear-gradient(135deg, #1a3a6e 0%, #0d5c3a 100%)",
      display:"flex", alignItems:"center", justifyContent:"center",
      boxShadow:"0 0 28px rgba(52,211,153,.4)",
      position:"relative", overflow:"hidden", flexShrink:0,
    }}>
      <svg width={size*0.72} height={size*0.72} viewBox="0 0 36 36" fill="none">
        <circle cx="18" cy="18" r="16" stroke="rgba(255,255,255,.15)" strokeWidth="1"/>
        <path d="M18 3 C9 3 3 9 3 18 C3 27 9 33 18 33" stroke="#34d399" strokeWidth="2" strokeLinecap="round"/>
        <path d="M18 3 C27 3 33 9 33 18 C33 27 27 33 18 33" stroke="rgba(255,255,255,.4)" strokeWidth="2" strokeLinecap="round"/>
        <path d="M9 18 L18 9 L27 18 L18 27 Z" fill="none" stroke="rgba(255,255,255,.5)" strokeWidth="1.5"/>
        <circle cx="18" cy="18" r="4" fill="#34d399"/>
        <path d="M18 3 L18 33 M3 18 L33 18" stroke="rgba(255,255,255,.12)" strokeWidth="1"/>
      </svg>
    </div>
  );
}

export default function Login({ onLogin, theme }) {
  const [form, setForm]       = useState({ nom:"rakoto", prenom:"zefa", email:"rakotozefa@gmail.com" });
  const [error, setError]     = useState("");
  const [loading, setLoading] = useState(false);
  const [mounted, setMounted] = useState(false);

  useEffect(() => { setTimeout(() => setMounted(true), 80); }, []);
  const set = (k, v) => setForm(f => ({ ...f, [k]: v }));

  const submit = (e) => {
    e.preventDefault();
    const nom    = form.nom.trim();
    const prenom = form.prenom.trim();
    const email  = form.email.trim();
    if (!nom || !prenom || !email) { setError("Tous les champs sont obligatoires."); return; }
    if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) { setError("Adresse e-mail invalide."); return; }
    setError("");
    setLoading(true);
    setTimeout(() => onLogin({ nom, prenom, email }), 900);
  };

  return (
    <div style={{ minHeight:"100vh", display:"flex", position:"relative", overflow:"hidden" }}>
      {/* Background */}
      <div style={{ position:"absolute", inset:0, backgroundImage:`url(${BG_IMAGE})`, backgroundSize:"cover", backgroundPosition:"center", filter:"brightness(.45) saturate(1.2)", zIndex:0 }} />
      <div style={{ position:"absolute", inset:0, zIndex:1, background:"linear-gradient(105deg, rgba(5,8,20,.92) 0%, rgba(5,8,20,.75) 52%, rgba(5,8,20,.5) 100%)" }} />
      <div style={{ position:"absolute", inset:0, zIndex:2, pointerEvents:"none", backgroundImage:"linear-gradient(rgba(108,143,255,.04) 1px, transparent 1px), linear-gradient(90deg, rgba(108,143,255,.04) 1px, transparent 1px)", backgroundSize:"48px 48px" }} />

      {/* Logo ISPM — haut droite */}
      <div style={{ position:"absolute", top:20, right:24, zIndex:20 }}>
        <img src={ISPM_LOGO} alt="ISPM" style={{ width:72, height:72, borderRadius:"50%", objectFit:"cover", border:"2px solid rgba(52,211,153,.5)", background:"#000", boxShadow:"0 0 24px rgba(52,211,153,.3)" }} />
      </div>

      {/* ── Panel gauche ── */}
      <div style={{ flex:"0 0 55%", display:"flex", flexDirection:"column", justifyContent:"center", padding:"60px 80px", position:"relative", zIndex:10, opacity:mounted?1:0, transform:mounted?"none":"translateX(-24px)", transition:"opacity .8s ease, transform .8s ease" }}>
        {/* Logo + nom */}
        <div style={{ display:"flex", alignItems:"center", gap:14, marginBottom:48 }}>
          <SfigpLogo size={58} />
          <div>
            <div style={{ fontFamily:"var(--font-head)", fontSize:28, fontWeight:900, color:"#fff", letterSpacing:"-.01em", lineHeight:1.1 }}>SFIGP</div>
            <div style={{ fontSize:10, color:"#34d399", fontWeight:700, letterSpacing:".14em", textTransform:"uppercase" }}>IGGLIA 3B — ISPM</div>
          </div>
        </div>

        {/* Titre */}
        <div style={{ marginBottom:40 }}>
          <div style={{ fontSize:11, fontWeight:700, letterSpacing:".18em", textTransform:"uppercase", color:"#6c8fff", marginBottom:14 }}>
            Système de présence — IGGLIA 3B
          </div>
          <h1 style={{ fontFamily:"var(--font-head)", fontSize:48, fontWeight:900, lineHeight:1.02, letterSpacing:"-.02em", marginBottom:16, background:"linear-gradient(135deg, #ffffff 0%, #a8bfff 100%)", WebkitBackgroundClip:"text", WebkitTextFillColor:"transparent" }}>
            Système facial<br/>intelligent de<br/>gestion de présence
          </h1>
          <p style={{ fontSize:15, color:"rgba(255,255,255,.5)", lineHeight:1.8, maxWidth:420 }}>
            Reconnaissance faciale en temps réel pour le suivi automatique des présences par cours.
          </p>
        </div>

        {/* Features */}
        {[
          { icon: <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#6c8fff" strokeWidth="2" strokeLinecap="round"><path d="M2 8V6a2 2 0 0 1 2-2h2"/><path d="M2 16v2a2 2 0 0 0 2 2h2"/><path d="M22 8V6a2 2 0 0 0-2-2h-2"/><path d="M22 16v2a2 2 0 0 1-2 2h-2"/><path d="M9 10h.01"/><path d="M15 10h.01"/><path d="M9.5 15a3.5 3.5 0 0 0 5 0"/></svg>, title:"Reconnaissance faciale", desc:"Identification automatique des élèves", color:"#6c8fff", bg:"rgba(108,143,255,.12)" },
          { icon: <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#fbbf24" strokeWidth="2" strokeLinecap="round"><circle cx="12" cy="12" r="9"/><path d="M12 7v5l3 3"/></svg>, title:"Présent / Retard automatique", desc:"Basé sur l'heure d'arrivée vs le cours", color:"#fbbf24", bg:"rgba(251,191,36,.1)" },
          { icon: <svg width="18" height="18" viewBox="0 0 24 24" fill="none" stroke="#34d399" strokeWidth="2" strokeLinecap="round"><rect x="5" y="2" width="14" height="20" rx="2"/><line x1="9" y1="7" x2="15" y2="7"/><line x1="9" y1="11" x2="15" y2="11"/><line x1="9" y1="15" x2="13" y2="15"/></svg>, title:"Historique complet", desc:"Groupé par cours, date et statut", color:"#34d399", bg:"rgba(52,211,153,.1)" },
        ].map((f, i) => (
          <div key={i} style={{ display:"flex", alignItems:"center", gap:14, marginBottom:13, opacity:mounted?1:0, transform:mounted?"none":"translateX(-10px)", transition:`opacity .6s ease ${0.3+i*0.13}s, transform .6s ease ${0.3+i*0.13}s` }}>
            <div style={{ width:42, height:42, borderRadius:11, flexShrink:0, background:f.bg, border:`1px solid ${f.color}30`, display:"flex", alignItems:"center", justifyContent:"center" }}>{f.icon}</div>
            <div>
              <div style={{ fontSize:13, fontWeight:600, color:"rgba(255,255,255,.9)" }}>{f.title}</div>
              <div style={{ fontSize:12, color:"rgba(255,255,255,.4)", marginTop:2 }}>{f.desc}</div>
            </div>
          </div>
        ))}
      </div>

      {/* ── Panel droit : formulaire ── */}
      <div style={{ flex:"0 0 45%", display:"flex", alignItems:"center", justifyContent:"center", padding:"40px", position:"relative", zIndex:10, opacity:mounted?1:0, transform:mounted?"none":"translateY(20px)", transition:"opacity .8s ease .15s, transform .8s ease .15s" }}>
        <div style={{ width:"100%", maxWidth:420, background:"rgba(13,15,20,.85)", border:"1px solid rgba(108,143,255,.2)", borderRadius:24, padding:"44px 40px", boxShadow:"0 8px 40px rgba(0,0,0,.6), 0 0 80px rgba(108,143,255,.08)", backdropFilter:"blur(24px)", WebkitBackdropFilter:"blur(24px)", position:"relative", overflow:"hidden" }}>
          <div style={{ position:"absolute", top:-1, right:-1, width:130, height:130, background:"linear-gradient(225deg, rgba(108,143,255,.1) 0%, transparent 60%)", borderTopRightRadius:24, pointerEvents:"none" }} />

          {/* Titre + logo SFIGP petit */}
          <div style={{ display:"flex", alignItems:"center", gap:12, marginBottom:24 }}>
            <SfigpLogo size={36} />
            <div>
              <h2 style={{ fontFamily:"var(--font-head)", fontSize:22, fontWeight:700, color:"#fff", margin:0, lineHeight:1.1 }}>Connexion</h2>
              <p style={{ fontSize:12, color:"rgba(255,255,255,.35)", marginTop:3 }}>Accès SFIGP — IGGLIA 3B</p>
            </div>
          </div>

          <form onSubmit={submit}>
            {/* Prénom */}
            <div style={{ marginBottom:14 }}>
              <label style={{ fontSize:10, fontWeight:700, letterSpacing:".1em", textTransform:"uppercase", color:"rgba(255,255,255,.4)", display:"block", marginBottom:6 }}>Prénom</label>
              <div style={{ position:"relative" }}>
                <svg style={{ position:"absolute", left:12, top:"50%", transform:"translateY(-50%)", opacity:.35 }} width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
                <input type="text" value={form.prenom} onChange={e => set("prenom", e.target.value)} placeholder="Ex : Zefa"
                  style={{ width:"100%", padding:"11px 13px 11px 36px", background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.1)", borderRadius:10, fontSize:14, color:"#fff", outline:"none" }}
                  onFocus={e => { e.target.style.borderColor="rgba(108,143,255,.6)"; e.target.style.boxShadow="0 0 0 3px rgba(108,143,255,.15)"; }}
                  onBlur={e => { e.target.style.borderColor="rgba(255,255,255,.1)"; e.target.style.boxShadow="none"; }}
                />
              </div>
            </div>
            {/* Nom */}
            <div style={{ marginBottom:14 }}>
              <label style={{ fontSize:10, fontWeight:700, letterSpacing:".1em", textTransform:"uppercase", color:"rgba(255,255,255,.4)", display:"block", marginBottom:6 }}>Nom</label>
              <div style={{ position:"relative" }}>
                <svg style={{ position:"absolute", left:12, top:"50%", transform:"translateY(-50%)", opacity:.35 }} width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round"><path d="M20 21v-2a4 4 0 0 0-4-4H8a4 4 0 0 0-4 4v2"/><circle cx="12" cy="7" r="4"/></svg>
                <input type="text" value={form.nom} onChange={e => set("nom", e.target.value)} placeholder="Ex : Rakoto"
                  style={{ width:"100%", padding:"11px 13px 11px 36px", background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.1)", borderRadius:10, fontSize:14, color:"#fff", outline:"none" }}
                  onFocus={e => { e.target.style.borderColor="rgba(108,143,255,.6)"; e.target.style.boxShadow="0 0 0 3px rgba(108,143,255,.15)"; }}
                  onBlur={e => { e.target.style.borderColor="rgba(255,255,255,.1)"; e.target.style.boxShadow="none"; }}
                />
              </div>
            </div>
            {/* Email */}
            <div style={{ marginBottom:22 }}>
              <label style={{ fontSize:10, fontWeight:700, letterSpacing:".1em", textTransform:"uppercase", color:"rgba(255,255,255,.4)", display:"block", marginBottom:6 }}>Adresse e-mail</label>
              <div style={{ position:"relative" }}>
                <svg style={{ position:"absolute", left:12, top:"50%", transform:"translateY(-50%)", opacity:.35 }} width="14" height="14" viewBox="0 0 24 24" fill="none" stroke="white" strokeWidth="2" strokeLinecap="round"><rect x="2" y="4" width="20" height="16" rx="2"/><path d="m22 7-8.97 5.7a1.94 1.94 0 0 1-2.06 0L2 7"/></svg>
                <input type="email" value={form.email} onChange={e => set("email", e.target.value)} placeholder="vous@exemple.com"
                  style={{ width:"100%", padding:"11px 13px 11px 36px", background:"rgba(255,255,255,.06)", border:"1px solid rgba(255,255,255,.1)", borderRadius:10, fontSize:14, color:"#fff", outline:"none" }}
                  onFocus={e => { e.target.style.borderColor="rgba(108,143,255,.6)"; e.target.style.boxShadow="0 0 0 3px rgba(108,143,255,.15)"; }}
                  onBlur={e => { e.target.style.borderColor="rgba(255,255,255,.1)"; e.target.style.boxShadow="none"; }}
                />
              </div>
            </div>
            {error && (
              <div style={{ display:"flex", alignItems:"center", gap:8, padding:"9px 13px", marginBottom:14, background:"rgba(248,113,113,.1)", border:"1px solid rgba(248,113,113,.25)", borderRadius:10, fontSize:12, color:"#f87171" }}>
                <svg width="13" height="13" viewBox="0 0 24 24" fill="none" stroke="#f87171" strokeWidth="2" strokeLinecap="round"><circle cx="12" cy="12" r="10"/><line x1="12" y1="8" x2="12" y2="12"/><line x1="12" y1="16" x2="12.01" y2="16"/></svg>
                {error}
              </div>
            )}
            <button type="submit" disabled={loading} style={{ width:"100%", padding:"13px", borderRadius:10, border:"none", background:loading?"rgba(255,255,255,.08)":"linear-gradient(135deg, #6c8fff, #4a6eff)", color:loading?"rgba(255,255,255,.4)":"#fff", fontSize:14, fontWeight:700, cursor:loading?"not-allowed":"pointer", boxShadow:loading?"none":"0 4px 24px rgba(108,143,255,.4)", transition:"all .2s", display:"flex", alignItems:"center", justifyContent:"center", gap:10 }}>
              {loading
                ? <><div style={{ width:15,height:15,border:"2px solid rgba(255,255,255,.3)",borderTopColor:"transparent",borderRadius:"50%",animation:"rotate360 .8s linear infinite" }} /> Connexion...</>
                : <>Accéder à SFIGP <svg width="15" height="15" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.5" strokeLinecap="round"><line x1="5" y1="12" x2="19" y2="12"/><polyline points="12 5 19 12 12 19"/></svg></>
              }
            </button>
          </form>

          <div style={{ marginTop:22, paddingTop:16, borderTop:"1px solid rgba(255,255,255,.07)", display:"flex", alignItems:"center", justifyContent:"space-between" }}>
            <div style={{ fontSize:11, color:"rgba(255,255,255,.25)" }}>Bienvenue</div>
            <div style={{ display:"flex", alignItems:"center", gap:6, fontSize:11, color:"rgba(255,255,255,.25)" }}>
              <svg width="11" height="11" viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round"><rect x="3" y="11" width="18" height="11" rx="2"/><path d="M7 11V7a5 5 0 0 1 10 0v4"/></svg>
              Accès réservé
            </div>
          </div>
        </div>
      </div>
    </div>
  );
}
